measure.command:
python3 -c 'import subprocess,time,urllib.request,sys
t=time.perf_counter()
p=subprocess.Popen("{{serve_command}}", shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
ok=False
while time.perf_counter()-t < 90:
    try:
        urllib.request.urlopen("{{url_base}}{{health_path}}", timeout=0.5); ok=True; break
    except Exception:
        time.sleep(0.02)
ms=(time.perf_counter()-t)*1000
p.terminate()
try: p.wait(5)
except Exception: p.kill()
print("METRIC cold_start_ms=%.0f" % ms)
sys.exit(0 if ok else 1)'
